head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====
scwin.onpageload = function () {
    var objDlt = $p.getComponentById("dlt_target");

    objDlt.bind("oncelldatachange", function (info) {
        scwin.setReturnValue("oncelldatachange : rowIndex=" + info.rowIndex + " / realRowIndex=" + info.realRowIndex);
    });
};

// col1_3 / col1_4 / col1_5 만 보이도록 필터를 적용한다 (앞 2 행이 걸러진다)
scwin.btn_filter_onclick = function (e) {
    var objDlt = $p.getComponentById("dlt_target");
    objDlt.clearFilter();
    objDlt.setColumnFilter({ type: 'row', colIndex: 'col1', key: "col1_3", condition: 'and' });
    objDlt.setColumnFilter({ type: 'row', colIndex: 'col1', key: "col1_4", condition: 'or' });
    objDlt.setColumnFilter({ type: 'row', colIndex: 'col1', key: "col1_5", condition: 'or' });
};
